      Effect    = "Allow",
      Principal = { Service = "lambda.amazonaws.com" }
    }]
  })
}

resource "aws_iam_role_policy" "create_task_policy" {
  name = "create_task_policy"
  role = aws_iam_role.create_task_role.id
